"""Tests for auto_generated_description.py."""
from retag_opus import auto_generated_description

AUTO_GENERATED_LINES = [
    "Provided to YouTube by Label",
    "Song · Singer · Other Singer",
    "Album",
    "℗ 2019 Label Records",
    "Released on: 2020-01-01",
    "Composer: Com Poser",
    "Auto-generated by YouTube.",
]


def test_find() -> None:
    """The auto-generated part is found among other lines."""
    lines = ["Our new video!"] + AUTO_GENERATED_LINES + ["Follow us"]
    assert auto_generated_description.find(lines) == (1, 7)


def test_find_without_layout() -> None:
    """Without the first, title or last line, there's no auto-generated part."""
    assert auto_generated_description.find(AUTO_GENERATED_LINES[:-1]) is None
    assert auto_generated_description.find(AUTO_GENERATED_LINES[1:]) is None
    changed_title_line = AUTO_GENERATED_LINES.copy()
    changed_title_line[1] = "Song • Singer"
    assert auto_generated_description.find(changed_title_line) is None


def test_parse() -> None:
    """Each line of the layout is put in its tag."""
    assert auto_generated_description.parse(AUTO_GENERATED_LINES) == {
        "organization": ["Label"],
        "title": ["Song"],
        "artist": ["Singer", "Other Singer"],
        "album": ["Album"],
        "copyright": ["2019 Label Records"],
        "date": ["2020-01-01"],
        "composer": ["Com Poser"],
    }


def test_parse_without_optional_lines() -> None:
    """The copyright year is the date when there's no release date."""
    lines = [
        "Provided to YouTube by Label",
        "Song · Singer, Other Singer",
        "Album",
        "℗ 2019 Label Records",
        "Auto-generated by YouTube.",
    ]
    tags = auto_generated_description.parse(lines)
    assert tags["artist"] == ["Singer", "Other Singer"]
    assert tags["date"] == ["2019"]
    lines = ["Provided to YouTube by Label", "Song · Singer", "Auto-generated by YouTube."]
    tags = auto_generated_description.parse(lines)
    assert tags == {"organization": ["Label"], "title": ["Song"], "artist": ["Singer"]}
